{"code": "import os
from hermes_tools import terminal

def main():
    home = os.path.expanduser('~')
    backup_base = os.path.join(home, 'hermes-backups')
    if not os.path.exists(backup_base):
        return "No hermes-backups directory."

    # List contents
    ls_result = terminal(command=f'ls -la "{backup_base}"')
    output = ls_result['output']

    # Check for temporary directory and tarball
    temp_dir = None
    tarball = None
    for line in output.split('\n'):
        if 'hermes_backup_' in line and line.endswith('/'):
            # Extract directory name
            parts = line.split()
            if len(parts) >= 9:
                temp_dir = os.path.join(backup_base, parts[8])
        if line.endswith('.tar.gz'):
            parts = line.split()
            if len(parts) >= 9:
                tarball = os.path.join(backup_base, parts[8])

    # Remove temporary directory if exists
    if temp_dir and os.path.exists(temp_dir):
        rm_result = terminal(command=f'rm -rf "{temp_dir}"')
        if rm_result['exit_code'] != 0:
            return f"Failed to remove temporary directory {temp_dir}: {rm_result.get('output', '')}"

    # Verify tarball
    if tarball and os.path.exists(tarball):
        size_result = terminal(command=f'du -h "{tarball}" | cut -f1')
        size = size_result['output'].strip() if size_result['exit_code'] == 0 else 'unknown'
        return f"Backup completed successfully.\nLocation: {tarball}\nSize: {size}"
    else:
        return "Backup tarball not found."

if __name__ == '__main__':
    print(main())"}
